/* --------------------------------------------------------------------------
 * Generate HsBaseConfig.h for the base package.
 *
 * This program replaces packages/base/configure.  It is compiled with the
 * same C compiler as Hugs and run at build time; its standard output is
 * HsBaseConfig.h.  It answers the one question that genuinely differs
 * between the supported targets, how each C type maps to a Haskell type
 * and what the errno and signal constants are, by asking the compiler and
 * the system headers directly.  Everything else is fixed per operating
 * system.
 *
 * Generated by scratch script gen_mkhsbaseconfig.py; edit this file, not
 * the script, which was a one-off.
 * ------------------------------------------------------------------------*/

/* Ask for the POSIX and BSD interfaces even when compiled as strict C */
#if !defined(_WIN32)
# define _DEFAULT_SOURCE 1
# define _DARWIN_C_SOURCE 1
#endif

#include <stdio.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
